  {%- endset -%}
  {{ include('ui/link-plain/link-plain.html.twig', {'p': {'Href': ui_s(v_href), 'Class': ui_s(v_outer), 'AriaCurrent': ui_s((ui_t(v_selected) ? 'page' : null)), 'Attrs': ui_attrs(['data-slot', 'nav-item', 'data-state', v_state])}, 'children': c_2}, with_context = false) }}
{%- elseif ui_t(v_interactive) %}
  {%- set c_4 -%}
    {%- set c_3 -%}
      {{ (children ?? '')|raw }}
    {%- endset -%}
    {{ include('blocks/nav-item-row.html.twig', {'p': {'inner': v_inner, 'reserveRight': v_reserveRight, 'icon': (p.icon ?? null), 'right': (p.right ?? null)}, 'children': c_3}, with_context = false) }}
  {%- endset -%}
  {{ include('ui/button-plain/button-plain.html.twig', {'p': {'Type': 'button', 'Class': ui_s(ui_cnv([v_outer, 'text-left'])), 'Attrs': ui_attrs(['aria-current', (ui_t(v_selected) ? 'page' : null), 'data-slot', 'nav-item', 'data-state', v_state])}, 'children': c_4}, with_context = false) }}
{%- else %}
